actions.script:
// LLM calls are CLIENT spans with OTel gen_ai.* attributes, under an AT_LLM frame named agent:, gateway:, assist: or
// mcp: (llm/provider/mod.rs). Calls are read newest first and grouped by trace here; the frames name each trace.
from = from || 'now-24h'; thru = thru || 'now'
const quote = value => '"'+String(value).replace(/\\/g,'\\\\').replace(/"/g,'\\"')+'"'
const clauses = ['gen_ai.operation.name:*']
if (provider) clauses.push('gen_ai.provider.name:'+quote(provider))
if (model) clauses.push('(gen_ai.request.model:'+quote(model)+' OR gen_ai.response.model:'+quote(model)+')')
queryNotices = []
const query = (queryString,pageSize,sort) => ec.service.sync().name('org.moqui.report.ReportServices.query#Documents').parameters({
    datasetId:'otel_spans',from,thru,queryString,pageSize,sort:sort || ['-time','-__cursor']}).call()
const options = (field) => {
    try {
        const output = ec.service.sync().name('org.moqui.report.ReportServices.run#Query').parameters({query:{datasetId:'otel_spans',from,thru,
            queryString:'gen_ai.operation.name:*',aggregations:[{id:'value',type:'terms',role:'x-axis',params:{field,size:50}}]}}).call()
        const frame=(output.frames || [])[0] || {fields:[]},values=frame.fields.find(item=>item.name==='value')
        return values ? values.values.filter(value=>value != null).map(value=>({value,text:value})) : []
    } catch (error) { queryNotices.push(String(error)); return [] }
}
providerOptions = options('gen_ai.provider.name'); modelOptions = options('gen_ai.request.model')
let calls = []
try {
    const result = query(clauses.join(' AND '),1000)
    calls = (result.hits || []).map(hit=>hit.body || {})
    if ((result.total || 0) > calls.length) queryNotices.push(ec.l10n.localize('Showing the traces of the newest {0} of {1} LLM calls; narrow the time range to see older ones.').replace('{0}',calls.length).replace('{1}',result.total))
    queryNotices.push(...(result.notices || []).map(notice=>typeof notice==='string'?notice:notice.message || JSON.stringify(notice)))
} catch (error) { queryNotices.push(String(error)) }
const number = value => { const parsed=Number(value); return Number.isFinite(parsed) ? parsed : 0 }
const traces = new Map()
for (const call of calls) {
    const id = call.trace_id; if (!id) continue
    let trace = traces.get(id)
    if (!trace) { trace = {traceId:id,started:call.start,calls:0,inputTokens:0,outputTokens:0,errors:0,maxMillis:0,models:new Set(),providers:new Set(),service:call['service.name'] || '',agent:''}; traces.set(id,trace) }
    trace.calls++
    trace.inputTokens += number(call['gen_ai.usage.input_tokens']); trace.outputTokens += number(call['gen_ai.usage.output_tokens'])
    if (call.status_code === 'ERROR') trace.errors++
    trace.maxMillis = Math.max(trace.maxMillis,number(call.duration_nano)/1000000)
    const model = call['gen_ai.response.model'] || call['gen_ai.request.model']; if (model) trace.models.add(model)
    if (call['gen_ai.provider.name']) trace.providers.add(call['gen_ai.provider.name'])
    if (String(call.start) < String(trace.started)) trace.started = call.start
}
// The AT_LLM frames of these traces give each one its agent, gateway or assist name (the outermost frame wins).
const ids = Array.from(traces.keys()).slice(0,200)
for (let at=0;at<ids.length;at+=50) {
    const batch = ids.slice(at,at+50)
    try {
        const frames = query('moqui.artifact.type:AT_LLM AND kind:INTERNAL AND trace_id:('+batch.join(' OR ')+')',1000,['start','__cursor'])
        for (const hit of frames.hits || []) {
            const frame = hit.body || {}, trace = traces.get(frame.trace_id)
            if (trace && !trace.agent) trace.agent = frame.name || frame['moqui.artifact.name'] || ''
        }
    } catch (error) { queryNotices.push(String(error)) }
}
traceList = Array.from(traces.values())
    .filter(trace => !agent || String(trace.agent).toLowerCase().includes(String(agent).toLowerCase()))
    .filter(trace => errorsOnly !== 'Y' || trace.errors > 0)
    .slice(0,200)
    .map(trace => Object.assign(trace,{models:Array.from(trace.models).join(', '),providers:Array.from(trace.providers).join(', '),
        totalTokens:trace.inputTokens+trace.outputTokens,maxMillis:Math.round(trace.maxMillis*10)/10}))
totals = traceList.reduce((sum,trace)=>({traces:sum.traces+1,calls:sum.calls+trace.calls,inputTokens:sum.inputTokens+trace.inputTokens,outputTokens:sum.outputTokens+trace.outputTokens,errors:sum.errors+trace.errors}),{traces:0,calls:0,inputTokens:0,outputTokens:0,errors:0})
